-- 0000_schema: every v0.1 table (S03). Generated by drizzle-kit from apps/server/src/db/schema, then
-- regrouped by module and reviewed by hand. docs/DB.md explains each table and invariant.
-- Conventions: ids are app-generated UUIDv7 (except bigint identity where noted), times are timestamptz
-- written from the server Clock (no now() defaults), money is bigint minimal units, enumerations are
-- text + CHECK. Invariant triggers, append-only rules and the app role live in 0001 and 0002.
-- Locking: runs on an empty database only; every statement creates a new object.

-- ===================================================================================
-- People and authentication
-- ===================================================================================
CREATE TABLE "users" (
	"id" uuid PRIMARY KEY NOT NULL,
	"email" text NOT NULL,
	"password_hash" text NOT NULL,
	"role" text NOT NULL,
	"display_name" text NOT NULL,
	"locale" text DEFAULT 'ko' NOT NULL,
	"terms_version" text,
	"terms_accepted_at" timestamp with time zone,
	"disabled_at" timestamp with time zone,
	"created_at" timestamp with time zone NOT NULL,
	"updated_at" timestamp with time zone NOT NULL,
	CONSTRAINT "users_role_check" CHECK ("role" IN ('operator', 'owner', 'buyer')),
	CONSTRAINT "users_email_check" CHECK (char_length("email") BETWEEN 3 AND 320 AND "email" LIKE '%_@_%'),
	CONSTRAINT "users_password_hash_check" CHECK (char_length("password_hash") BETWEEN 1 AND 512),
	CONSTRAINT "users_display_name_check" CHECK (char_length("display_name") BETWEEN 1 AND 100),
	CONSTRAINT "users_locale_check" CHECK ("locale" ~ '^[a-z]{2}(-[A-Z]{2})?$'),
	CONSTRAINT "users_terms_check" CHECK (("terms_version" IS NULL) = ("terms_accepted_at" IS NULL) AND char_length("terms_version") <= 32)
);--> statement-breakpoint
CREATE TABLE "sessions" (
	"id" uuid PRIMARY KEY NOT NULL,
	"user_id" uuid NOT NULL,
	"token_hash" bytea NOT NULL,
	"created_at" timestamp with time zone NOT NULL,
	"last_seen_at" timestamp with time zone NOT NULL,
	"expires_at" timestamp with time zone NOT NULL,
	"revoked_at" timestamp with time zone,
	"ip_hash" bytea,
	CONSTRAINT "sessions_token_hash_key" UNIQUE("token_hash"),
	CONSTRAINT "sessions_token_hash_check" CHECK (octet_length("token_hash") = 32),
	CONSTRAINT "sessions_expiry_check" CHECK ("expires_at" > "created_at")
);--> statement-breakpoint
CREATE TABLE "api_keys" (
	"id" uuid PRIMARY KEY NOT NULL,
	"user_id" uuid NOT NULL,
	"name" text NOT NULL,
	"prefix" text NOT NULL,
	"key_hash" bytea NOT NULL,
	"hash_key_id" text NOT NULL,
	"scopes" text[] DEFAULT '{}'::text[] NOT NULL,
	"rate_limit_rpm" integer,
	"created_at" timestamp with time zone NOT NULL,
	"last_used_at" timestamp with time zone,
	"expires_at" timestamp with time zone,
	"revoked_at" timestamp with time zone,
	CONSTRAINT "api_keys_prefix_key" UNIQUE("prefix"),
	CONSTRAINT "api_keys_key_hash_key" UNIQUE("key_hash"),
	CONSTRAINT "api_keys_name_check" CHECK (char_length("name") BETWEEN 1 AND 100),
	CONSTRAINT "api_keys_prefix_check" CHECK ("prefix" ~ '^[A-Za-z0-9_]{8,32}$'),
	CONSTRAINT "api_keys_key_hash_check" CHECK (octet_length("key_hash") = 32),
	CONSTRAINT "api_keys_hash_key_id_check" CHECK ("hash_key_id" ~ '^[a-z0-9][a-z0-9-]{0,31}$'),
	CONSTRAINT "api_keys_scopes_check" CHECK (cardinality("scopes") <= 16),
	CONSTRAINT "api_keys_rate_limit_check" CHECK ("rate_limit_rpm" IS NULL OR "rate_limit_rpm" > 0)
);--> statement-breakpoint
CREATE TABLE "idempotency_keys" (
	"scope" text NOT NULL,
	"key" text NOT NULL,
	"request_hash" bytea NOT NULL,
	"status" text NOT NULL,
	"response_status" integer,
	"response" jsonb,
	"created_at" timestamp with time zone NOT NULL,
	"completed_at" timestamp with time zone,
	"expires_at" timestamp with time zone NOT NULL,
	CONSTRAINT "idempotency_keys_pkey" PRIMARY KEY("scope","key"),
	CONSTRAINT "idempotency_keys_scope_check" CHECK (char_length("scope") BETWEEN 1 AND 200),
	CONSTRAINT "idempotency_keys_key_check" CHECK ("key" ~ '^[\x21-\x7e]{1,255}$'),
	CONSTRAINT "idempotency_keys_request_hash_check" CHECK (octet_length("request_hash") = 32),
	CONSTRAINT "idempotency_keys_status_check" CHECK ("status" IN ('in_progress', 'completed')),
	CONSTRAINT "idempotency_keys_completed_check" CHECK (("status" = 'completed') = ("completed_at" IS NOT NULL)),
	CONSTRAINT "idempotency_keys_response_check" CHECK ("response" IS NULL OR pg_column_size("response") <= 4096),
	CONSTRAINT "idempotency_keys_expiry_check" CHECK ("expires_at" > "created_at")
);--> statement-breakpoint

-- ===================================================================================
-- Stores and nodes
-- ===================================================================================
CREATE TABLE "stores" (
	"id" uuid PRIMARY KEY NOT NULL,
	"owner_id" uuid NOT NULL,
	"name" text NOT NULL,
	"timezone" text DEFAULT 'Asia/Seoul' NOT NULL,
	"electricity_won_per_kwh" bigint,
	"policy" jsonb NOT NULL,
	"policy_version" integer DEFAULT 1 NOT NULL,
	"store_salt" text NOT NULL,
	"accept_tcr_jobs" boolean DEFAULT true NOT NULL,
	"verified_at" timestamp with time zone,
	"verified_by" uuid,
	"paused_at" timestamp with time zone,
	"last_public_ip_hmac" text,
	"last_public_ip_at" timestamp with time zone,
	"created_at" timestamp with time zone NOT NULL,
	"updated_at" timestamp with time zone NOT NULL,
	CONSTRAINT "stores_name_check" CHECK (char_length("name") BETWEEN 1 AND 100),
	CONSTRAINT "stores_timezone_check" CHECK ("timezone" ~ '^[A-Za-z_]+(/[A-Za-z0-9_+-]+){0,2}$'),
	CONSTRAINT "stores_electricity_check" CHECK ("electricity_won_per_kwh" IS NULL OR "electricity_won_per_kwh" >= 0),
	CONSTRAINT "stores_policy_version_check" CHECK ("policy_version" >= 1),
	CONSTRAINT "stores_policy_size_check" CHECK (pg_column_size("policy") <= 16384),
	CONSTRAINT "stores_store_salt_check" CHECK ("store_salt" ~ '^[0-9a-f]{64}$'),
	CONSTRAINT "stores_verified_check" CHECK (("verified_at" IS NULL) = ("verified_by" IS NULL)),
	CONSTRAINT "stores_last_public_ip_check" CHECK (("last_public_ip_hmac" IS NULL) = ("last_public_ip_at" IS NULL) AND ("last_public_ip_hmac" IS NULL OR "last_public_ip_hmac" ~ '^[0-9a-f]{64}$'))
);--> statement-breakpoint
CREATE TABLE "enrollment_codes" (
	"id" uuid PRIMARY KEY NOT NULL,
	"store_id" uuid NOT NULL,
	"code_hash" bytea NOT NULL,
	"kind" text NOT NULL,
	"max_uses" integer NOT NULL,
	"uses" integer DEFAULT 0 NOT NULL,
	"created_by" uuid NOT NULL,
	"created_at" timestamp with time zone NOT NULL,
	"expires_at" timestamp with time zone NOT NULL,
	"revoked_at" timestamp with time zone,
	CONSTRAINT "enrollment_codes_code_hash_key" UNIQUE("code_hash"),
	CONSTRAINT "enrollment_codes_kind_check" CHECK ("kind" IN ('single', 'image')),
	CONSTRAINT "enrollment_codes_code_hash_check" CHECK (octet_length("code_hash") = 32),
	CONSTRAINT "enrollment_codes_uses_check" CHECK ("max_uses" >= 1 AND "uses" >= 0 AND "uses" <= "max_uses"),
	CONSTRAINT "enrollment_codes_single_check" CHECK ("kind" <> 'single' OR "max_uses" = 1),
	CONSTRAINT "enrollment_codes_expiry_check" CHECK ("expires_at" > "created_at")
);--> statement-breakpoint
CREATE TABLE "nodes" (
	"id" uuid PRIMARY KEY NOT NULL,
	"store_id" uuid NOT NULL,
	"display_name" text NOT NULL,
	"device_pubkey" text NOT NULL,
	"fp_store" text NOT NULL,
	"fp_global" text NOT NULL,
	"state" text NOT NULL,
	"eligible" boolean DEFAULT false NOT NULL,
	"ineligible_reason" text,
	"state_changed_at" timestamp with time zone NOT NULL,
	"last_seen_at" timestamp with time zone,
	"agent_version" text,
	"runtime_version" text,
	"os_build" text,
	"gpu_summary" jsonb,
	"reputation_ppm" integer DEFAULT 500000 NOT NULL,
	"quarantined_at" timestamp with time zone,
	"quarantine_reason" text,
	"excluded_at" timestamp with time zone,
	"excluded_reason" text,
	"disabled_at" timestamp with time zone,
	"reattached_at" timestamp with time zone,
	"created_at" timestamp with time zone NOT NULL,
	"updated_at" timestamp with time zone NOT NULL,
	CONSTRAINT "nodes_device_pubkey_key" UNIQUE("device_pubkey"),
	CONSTRAINT "nodes_store_fp_store_key" UNIQUE("store_id","fp_store"),
	CONSTRAINT "nodes_state_check" CHECK ("state" IN ('pending', 'offline', 'idle', 'customer', 'running', 'paused', 'quarantined', 'excluded', 'disabled')),
	CONSTRAINT "nodes_display_name_check" CHECK (char_length("display_name") BETWEEN 1 AND 128),
	CONSTRAINT "nodes_device_pubkey_check" CHECK ("device_pubkey" ~ '^[0-9a-f]{64}$'),
	CONSTRAINT "nodes_fp_store_check" CHECK ("fp_store" ~ '^[0-9a-f]{64}$'),
	CONSTRAINT "nodes_fp_global_check" CHECK ("fp_global" ~ '^[0-9a-f]{64}$'),
	CONSTRAINT "nodes_ineligible_reason_check" CHECK ("ineligible_reason" IS NULL OR "ineligible_reason" ~ '^[a-z][a-z0-9_.]{0,63}$'),
	CONSTRAINT "nodes_versions_check" CHECK (("agent_version" IS NULL OR "agent_version" ~ '^[A-Za-z0-9._+-]{1,64}$')
        AND ("runtime_version" IS NULL OR "runtime_version" ~ '^[A-Za-z0-9._+-]{1,64}$')
        AND ("os_build" IS NULL OR "os_build" ~ '^[A-Za-z0-9._+-]{1,64}$')),
	CONSTRAINT "nodes_gpu_summary_check" CHECK ("gpu_summary" IS NULL OR pg_column_size("gpu_summary") <= 8192),
	CONSTRAINT "nodes_reputation_check" CHECK ("reputation_ppm" BETWEEN 0 AND 1000000),
	CONSTRAINT "nodes_state_timestamps_check" CHECK (("state" <> 'quarantined' OR "quarantined_at" IS NOT NULL)
        AND ("state" <> 'excluded' OR "excluded_at" IS NOT NULL)
        AND ("state" <> 'disabled' OR "disabled_at" IS NOT NULL)),
	CONSTRAINT "nodes_reasons_check" CHECK (char_length("quarantine_reason") <= 500 AND char_length("excluded_reason") <= 500)
);--> statement-breakpoint
CREATE TABLE "node_events" (
	"id" uuid PRIMARY KEY NOT NULL,
	"node_id" uuid NOT NULL,
	"at" timestamp with time zone NOT NULL,
	"kind" text NOT NULL,
	"data" jsonb DEFAULT '{}'::jsonb NOT NULL,
	CONSTRAINT "node_events_kind_check" CHECK ("kind" ~ '^[a-z][a-z0-9_.]{0,63}$'),
	CONSTRAINT "node_events_data_check" CHECK (pg_column_size("data") <= 8192)
);--> statement-breakpoint
CREATE TABLE "presence_intervals" (
	"id" uuid PRIMARY KEY NOT NULL,
	"node_id" uuid NOT NULL,
	"kind" text NOT NULL,
	"started_at" timestamp with time zone NOT NULL,
	"ended_at" timestamp with time zone,
	CONSTRAINT "presence_intervals_kind_check" CHECK ("kind" IN ('eligible', 'ineligible', 'customer', 'paused', 'offline')),
	CONSTRAINT "presence_intervals_range_check" CHECK ("ended_at" IS NULL OR "ended_at" >= "started_at")
);--> statement-breakpoint
CREATE TABLE "kill_switches" (
	"id" uuid PRIMARY KEY NOT NULL,
	"scope" text NOT NULL,
	"store_id" uuid,
	"node_id" uuid,
	"reason" text NOT NULL,
	"created_by" uuid NOT NULL,
	"created_at" timestamp with time zone NOT NULL,
	"released_at" timestamp with time zone,
	"released_by" uuid,
	CONSTRAINT "kill_switches_scope_check" CHECK ("scope" IN ('global', 'store', 'node')),
	CONSTRAINT "kill_switches_target_check" CHECK (("scope" = 'global' AND "store_id" IS NULL AND "node_id" IS NULL)
        OR ("scope" = 'store' AND "store_id" IS NOT NULL AND "node_id" IS NULL)
        OR ("scope" = 'node' AND "node_id" IS NOT NULL AND "store_id" IS NULL)),
	CONSTRAINT "kill_switches_reason_check" CHECK (char_length("reason") BETWEEN 1 AND 500),
	CONSTRAINT "kill_switches_release_check" CHECK (("released_at" IS NULL) = ("released_by" IS NULL))
);--> statement-breakpoint

-- ===================================================================================
-- Models and releases
-- ===================================================================================
CREATE TABLE "models" (
	"id" uuid PRIMARY KEY NOT NULL,
	"slug" text NOT NULL,
	"display_name" text NOT NULL,
	"family" text NOT NULL,
	"provider" text DEFAULT 'node' NOT NULL,
	"provider_model" text,
	"params_millions" integer,
	"quantization" text,
	"context_len" integer NOT NULL,
	"min_vram_mb" integer,
	"license" text NOT NULL,
	"license_url" text,
	"source_url" text,
	"commercial_use_ok" boolean NOT NULL,
	"status" text NOT NULL,
	"created_at" timestamp with time zone NOT NULL,
	"updated_at" timestamp with time zone NOT NULL,
	"activated_at" timestamp with time zone,
	"retired_at" timestamp with time zone,
	CONSTRAINT "models_slug_key" UNIQUE("slug"),
	CONSTRAINT "models_slug_check" CHECK ("slug" ~ '^[a-z0-9][a-z0-9._-]{0,63}$'),
	CONSTRAINT "models_display_name_check" CHECK (char_length("display_name") BETWEEN 1 AND 100),
	CONSTRAINT "models_family_check" CHECK (char_length("family") BETWEEN 1 AND 64),
	CONSTRAINT "models_provider_check" CHECK ("provider" IN ('node', 'anthropic')),
	CONSTRAINT "models_provider_model_check" CHECK (("provider" = 'node') = ("provider_model" IS NULL) AND char_length("provider_model") <= 100),
	CONSTRAINT "models_sizes_check" CHECK (("params_millions" IS NULL OR "params_millions" > 0) AND "context_len" > 0
        AND ("min_vram_mb" IS NULL OR "min_vram_mb" >= 0)),
	CONSTRAINT "models_texts_check" CHECK (char_length("license") BETWEEN 1 AND 100 AND char_length("quantization") <= 32
        AND char_length("license_url") <= 800 AND char_length("source_url") <= 800),
	CONSTRAINT "models_status_check" CHECK ("status" IN ('draft', 'active', 'retired')),
	CONSTRAINT "models_status_times_check" CHECK (("status" <> 'active' OR "activated_at" IS NOT NULL)
        AND ("status" <> 'retired' OR "retired_at" IS NOT NULL))
);--> statement-breakpoint
CREATE TABLE "model_artifacts" (
	"id" uuid PRIMARY KEY NOT NULL,
	"model_id" uuid NOT NULL,
	"kind" text NOT NULL,
	"sha256" text NOT NULL,
	"size_bytes" bigint NOT NULL,
	"storage_key" text NOT NULL,
	"signature" text,
	"created_at" timestamp with time zone NOT NULL,
	CONSTRAINT "model_artifacts_model_sha256_key" UNIQUE("model_id","sha256"),
	CONSTRAINT "model_artifacts_kind_check" CHECK ("kind" IN ('gguf', 'tokenizer', 'chat_template')),
	CONSTRAINT "model_artifacts_sha256_check" CHECK ("sha256" ~ '^[0-9a-f]{64}$'),
	CONSTRAINT "model_artifacts_size_check" CHECK ("size_bytes" > 0),
	CONSTRAINT "model_artifacts_storage_key_check" CHECK (char_length("storage_key") BETWEEN 1 AND 512),
	CONSTRAINT "model_artifacts_signature_check" CHECK ("signature" IS NULL OR "signature" ~ '^[0-9a-f]{128}$')
);--> statement-breakpoint
CREATE TABLE "runtime_releases" (
	"id" uuid PRIMARY KEY NOT NULL,
	"name" text NOT NULL,
	"version" text NOT NULL,
	"platform" text NOT NULL,
	"sha256" text NOT NULL,
	"size_bytes" bigint NOT NULL,
	"storage_key" text NOT NULL,
	"signature" text,
	"status" text NOT NULL,
	"created_at" timestamp with time zone NOT NULL,
	CONSTRAINT "runtime_releases_name_version_platform_key" UNIQUE("name","version","platform"),
	CONSTRAINT "runtime_releases_name_check" CHECK ("name" IN ('llamacpp', 'ollama')),
	CONSTRAINT "runtime_releases_version_check" CHECK ("version" ~ '^[A-Za-z0-9._+-]{1,64}$'),
	CONSTRAINT "runtime_releases_platform_check" CHECK ("platform" ~ '^[A-Za-z0-9._+-]{1,64}$'),
	CONSTRAINT "runtime_releases_sha256_check" CHECK ("sha256" ~ '^[0-9a-f]{64}$'),
	CONSTRAINT "runtime_releases_size_check" CHECK ("size_bytes" > 0),
	CONSTRAINT "runtime_releases_storage_key_check" CHECK (char_length("storage_key") BETWEEN 1 AND 512),
	CONSTRAINT "runtime_releases_signature_check" CHECK ("signature" IS NULL OR "signature" ~ '^[0-9a-f]{128}$'),
	CONSTRAINT "runtime_releases_status_check" CHECK ("status" IN ('draft', 'active', 'retired')),
	CONSTRAINT "runtime_releases_signed_check" CHECK ("status" = 'draft' OR "signature" IS NOT NULL)
);--> statement-breakpoint
CREATE TABLE "agent_releases" (
	"id" uuid PRIMARY KEY NOT NULL,
	"version" text NOT NULL,
	"sha256" text NOT NULL,
	"size_bytes" bigint NOT NULL,
	"storage_key" text NOT NULL,
	"manifest" jsonb,
	"signature" text,
	"signing_key_id" text,
	"status" text NOT NULL,
	"rollout_percent" smallint DEFAULT 0 NOT NULL,
	"target_store_ids" uuid[] DEFAULT '{}'::uuid[] NOT NULL,
	"created_at" timestamp with time zone NOT NULL,
	"signed_at" timestamp with time zone,
	"rollout_started_at" timestamp with time zone,
	"completed_at" timestamp with time zone,
	CONSTRAINT "agent_releases_version_key" UNIQUE("version"),
	CONSTRAINT "agent_releases_version_check" CHECK ("version" ~ '^(0|[1-9][0-9]{0,4})\.(0|[1-9][0-9]{0,4})\.(0|[1-9][0-9]{0,4})(-[0-9A-Za-z][0-9A-Za-z.-]{0,31})?$'),
	CONSTRAINT "agent_releases_sha256_check" CHECK ("sha256" ~ '^[0-9a-f]{64}$'),
	CONSTRAINT "agent_releases_size_check" CHECK ("size_bytes" > 0),
	CONSTRAINT "agent_releases_storage_key_check" CHECK (char_length("storage_key") BETWEEN 1 AND 512),
	CONSTRAINT "agent_releases_status_check" CHECK ("status" IN ('draft', 'signed', 'rolling_out', 'paused', 'completed', 'rolled_back', 'revoked')),
	CONSTRAINT "agent_releases_rollout_check" CHECK ("rollout_percent" BETWEEN 0 AND 100),
	CONSTRAINT "agent_releases_targets_check" CHECK (cardinality("target_store_ids") <= 1000),
	CONSTRAINT "agent_releases_signed_check" CHECK ("status" IN ('draft', 'revoked')
        OR ("signature" IS NOT NULL AND "manifest" IS NOT NULL AND "signing_key_id" IS NOT NULL AND "signed_at" IS NOT NULL)),
	CONSTRAINT "agent_releases_signature_check" CHECK (("signature" IS NULL OR "signature" ~ '^[0-9a-f]{128}$')
        AND ("signing_key_id" IS NULL OR "signing_key_id" ~ '^[a-z0-9][a-z0-9-]{0,31}$')
        AND ("manifest" IS NULL OR pg_column_size("manifest") <= 131072))
);--> statement-breakpoint

-- ===================================================================================
-- Prices and exchange rates (append-only, see 0001)
-- ===================================================================================
CREATE TABLE "price_versions" (
	"id" uuid PRIMARY KEY NOT NULL,
	"version" integer NOT NULL,
	"notes" text,
	"effective_at" timestamp with time zone NOT NULL,
	"created_by" uuid,
	"created_at" timestamp with time zone NOT NULL,
	CONSTRAINT "price_versions_version_key" UNIQUE("version"),
	CONSTRAINT "price_versions_version_check" CHECK ("version" >= 1),
	CONSTRAINT "price_versions_notes_check" CHECK (char_length("notes") <= 1000)
);--> statement-breakpoint
CREATE TABLE "price_entries" (
	"price_version_id" uuid NOT NULL,
	"model_id" uuid NOT NULL,
	"input_ucr_per_mtok" bigint NOT NULL,
	"output_ucr_per_mtok" bigint NOT NULL,
	"node_payout_bps" integer NOT NULL,
	"provider_cost_uusd_per_mtok_in" bigint,
	"provider_cost_uusd_per_mtok_out" bigint,
	CONSTRAINT "price_entries_pkey" PRIMARY KEY("price_version_id","model_id"),
	CONSTRAINT "price_entries_prices_check" CHECK ("input_ucr_per_mtok" >= 0 AND "output_ucr_per_mtok" >= 0),
	CONSTRAINT "price_entries_payout_bps_check" CHECK ("node_payout_bps" BETWEEN 0 AND 10000),
	CONSTRAINT "price_entries_provider_cost_check" CHECK (("provider_cost_uusd_per_mtok_in" IS NULL OR "provider_cost_uusd_per_mtok_in" >= 0)
        AND ("provider_cost_uusd_per_mtok_out" IS NULL OR "provider_cost_uusd_per_mtok_out" >= 0))
);--> statement-breakpoint
CREATE TABLE "fx_rates" (
	"id" uuid PRIMARY KEY NOT NULL,
	"pair" text NOT NULL,
	"rate_micros" bigint NOT NULL,
	"source" text NOT NULL,
	"effective_at" timestamp with time zone NOT NULL,
	"created_by" uuid,
	"created_at" timestamp with time zone NOT NULL,
	CONSTRAINT "fx_rates_pair_check" CHECK ("pair" ~ '^[A-Z]{3}/[A-Z]{3}$'),
	CONSTRAINT "fx_rates_rate_check" CHECK ("rate_micros" > 0),
	CONSTRAINT "fx_rates_source_check" CHECK (char_length("source") BETWEEN 1 AND 100)
);--> statement-breakpoint

-- ===================================================================================
-- Ledger (invariant triggers in 0001)
-- ===================================================================================
CREATE TABLE "ledger_accounts" (
	"id" uuid PRIMARY KEY NOT NULL,
	"kind" text NOT NULL,
	"owner_type" text NOT NULL,
	"owner_id" uuid,
	"currency" text NOT NULL,
	"shard" smallint DEFAULT 0 NOT NULL,
	"allow_negative" boolean DEFAULT false NOT NULL,
	"created_at" timestamp with time zone NOT NULL,
	CONSTRAINT "ledger_accounts_identity_key" UNIQUE NULLS NOT DISTINCT("kind","owner_type","owner_id","currency","shard"),
	CONSTRAINT "ledger_accounts_id_currency_key" UNIQUE("id","currency"),
	CONSTRAINT "ledger_accounts_id_currency_negative_key" UNIQUE("id","currency","allow_negative"),
	CONSTRAINT "ledger_accounts_kind_check" CHECK ("kind" IN ('buyer_wallet', 'buyer_hold', 'store_pending', 'store_matured', 'payout_in_progress', 'platform_revenue', 'platform_verification', 'external_exchange', 'suspense', 'reserve', 'external_spend', 'payout_paid', 'fx_conversion', 'test_topup_source', 'sandbox_issuance')),
	CONSTRAINT "ledger_accounts_owner_type_check" CHECK ("owner_type" IN ('user', 'store', 'platform')),
	CONSTRAINT "ledger_accounts_currency_check" CHECK ("currency" IN ('CR', 'TCR', 'KRW', 'USD')),
	CONSTRAINT "ledger_accounts_owner_id_check" CHECK (("owner_type" = 'platform') = ("owner_id" IS NULL)),
	CONSTRAINT "ledger_accounts_shard_check" CHECK ("shard" BETWEEN 0 AND 255),
	CONSTRAINT "ledger_accounts_kind_owner_check" CHECK (("kind" IN ('buyer_wallet', 'buyer_hold') AND "owner_type" = 'user') OR ("kind" IN ('store_pending', 'store_matured', 'payout_in_progress') AND "owner_type" = 'store') OR ("kind" IN ('platform_revenue', 'platform_verification', 'external_exchange', 'suspense', 'reserve', 'external_spend', 'payout_paid', 'fx_conversion', 'test_topup_source', 'sandbox_issuance') AND "owner_type" = 'platform')),
	CONSTRAINT "ledger_accounts_kind_currency_check" CHECK (("currency" = 'CR' AND "kind" IN ('buyer_wallet', 'buyer_hold', 'store_pending', 'store_matured', 'payout_in_progress', 'platform_revenue', 'platform_verification', 'external_exchange', 'suspense', 'fx_conversion')) OR ("currency" = 'TCR' AND "kind" IN ('buyer_wallet', 'buyer_hold', 'store_pending', 'store_matured', 'platform_revenue', 'platform_verification', 'suspense', 'sandbox_issuance')) OR ("currency" = 'KRW' AND "kind" IN ('reserve', 'external_spend', 'payout_paid', 'fx_conversion', 'test_topup_source')) OR ("currency" = 'USD' AND "kind" IN ('external_spend', 'fx_conversion'))),
	CONSTRAINT "ledger_accounts_negative_check" CHECK (NOT "allow_negative" OR "kind" IN ('external_spend', 'payout_paid', 'fx_conversion', 'test_topup_source', 'sandbox_issuance'))
);--> statement-breakpoint
CREATE TABLE "ledger_transactions" (
	"id" uuid PRIMARY KEY NOT NULL,
	"kind" text NOT NULL,
	"idempotency_key" text NOT NULL,
	"memo" text,
	"reverses_tx_id" uuid,
	"created_by" uuid,
	"created_at" timestamp with time zone NOT NULL,
	"metadata" jsonb DEFAULT '{}'::jsonb NOT NULL,
	"fx_rate_id" uuid,
	"created_xid" xid8 DEFAULT pg_current_xact_id() NOT NULL,
	CONSTRAINT "ledger_transactions_idempotency_key" UNIQUE("idempotency_key"),
	CONSTRAINT "ledger_transactions_reverses_key" UNIQUE("reverses_tx_id"),
